```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::{http_client, state_read};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment fetch (approved grant). RunInfo has no text field, so the
        // date string is used as the query. The result is deliberately ignored,
        // and failures are values, so the node's output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let urls = match state_read::get("subscriptions") {
            Some(text) => text
                .lines()
                .map(|l| l.trim())
                .filter(|l| !l.is_empty())
                .map(|l| l.to_string())
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
```

